{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Konklusionen er korrekt: arbejdsophør giver ikke i sig selv ret, og UDK vurderer arbejdets karakter, andre jobtyper og skånehensyn/mindre omfang. Det stemmer med rubrikken og vejledningens afsnit 3.4.1.3. Formuleringen 'stort set ikke muligt at påtage sig erhvervsarbejde i nævneværdigt omfang' er en skærpet parafrase, men ikke en væsentlig juridisk fejl i forhold til 'meget betydelige begrænsninger'."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: arbejdets karakter holdes op mod funktionsnedsættelsen, andre typer arbejde vurderes, og skånehensyn eller mindre omfang indgår. Brugen af sagens øvrige oplysninger er kun delvist eksplicit, men dækkes ved vurderingen af andet arbejde og dokumentationen."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: om arbejdsophør i sig selv giver ret (nej), og hvad Udbetaling Danmark vurderer. Teksten er relevant."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: Vejledning nr. 10157 og SU-bekendtgørelsen nr. 841. De væsentlige udsagn kan føres tilbage hertil. Henvisningerne er dog uspecifikke, kun tal i teksten og en kildeliste uden præcise paragraffer."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De angivne kilder er den aktuelle vejledning og SU-bekendtgørelsen, som begge ligger inden for den frosne kildeafgrænsning og er autoritative og anvendelige."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke fuldt af de angivne passager. Det gælder formuleringen 'stort set ikke muligt ... i nævneværdigt omfang', at UDK 'typisk' spørger om 'varige og alvorlige begrænsninger', og at ophør er 'et stærkt argument'. Det gælder også 'og ikke andre forhold' om, at ophøret faktisk skyldes funktionsnedsættelsen. Det er heller ikke dokumenteret, at ophør 'indgår som et relevant moment'. Kildelisten viser kun uddrag og ikke de konkrete bestemmelser."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer indhold uden støtte i materialet. Tærsklen 'stort set ikke muligt ... i nævneværdigt omfang' er ikke i kilderne. Det samme gælder, at UDK skal vurdere, om ophøret faktisk skyldes funktionsnedsættelsen og ikke andre forhold, samt at ophør er 'et stærkt argument'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "De påkrævede forbehold er bevaret: arbejdsophør er et udgangspunkt for nærmere vurdering og afgør ikke retten alene. Det fremgår også, at ikke-fysisk belastende arbejde er et eksempel ('også i arbejde der ikke er fysisk belastende') og ikke en selvstændig betingelse."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Argumentationen er sammenhængende: arbejdsophør er relevant, men ikke afgørende, og der skal foretages en konkret vurdering af arbejdets karakter og alternative muligheder. Konklusionen følger heraf."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Modaliteten er delvist upræcis. 'Stort set ikke muligt' skærper standarden. 'Skal stadig vurdere' og 'varige og alvorlige' gengives mere absolut end kilden. Formuleringen 'er ikke nok' for en bestemt funktionsnedsættelse er stærkere end vejledningens 'ikke muligt at udarbejde en positivliste'."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "yes",
      "reason": "Svaret behandler situationen, hvor ansøgeren oplyser at være ophørt i arbejde på grund af funktionsnedsættelsen, og angiver, at UDK ser på arbejdets karakter i forhold til funktionsnedsættelsen."
    },
    "A23": {
      "label": "yes",
      "reason": "Svaret angiver, at UDK vurderer, om ansøgeren kan varetage andet arbejde, eventuelt med skånehensyn eller i mindre omfang, og nævner ikke-fysisk belastende arbejde."
    }
  },
  "overall_notes": "Kernen er juridisk korrekt og dækker rubrikkens kritiske elementer. Svaret tilføjer dog en skærpet tærskelformulering ('stort set ikke muligt ... i nævneværdigt omfang') og en kausalitetsvurdering ('ikke andre forhold') uden støtte i de udleverede kilder. Det trækker C06, C07 og C10 ned."
}

